package com.phoenix.vpn

import android.app.Activity
import android.app.AlertDialog
import android.content.Intent
import android.net.VpnService
import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.widget.*
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.core.splashscreen.SplashScreen.Companion.installSplashScreen
import androidx.core.content.ContextCompat
import org.json.JSONObject

class MainActivity:AppCompatActivity(){
    private lateinit var repo:ConfigRepository; private lateinit var root:LinearLayout; private var connected=false; private var started=0L
    private val importDoc=registerForActivityResult(ActivityResultContracts.OpenDocument()){uri->uri?.let{try{val text=contentResolver.openInputStream(it)?.bufferedReader()?.readText().orEmpty();showImport(text)}catch(e:Exception){toast("Import failed: ${e.message}")}}}
    override fun onCreate(savedInstanceState:Bundle?){installSplashScreen();super.onCreate(savedInstanceState);repo=ConfigRepository(this);window.statusBarColor=0xff120b22.toInt();showHome()}
    private fun base(title:String){root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(20,16,20,20);setBackgroundColor(0xff120b22.toInt())}; val bar=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL}; val menu=button("☰"){drawer()};val heading=text(title,22,true);bar.addView(menu);bar.addView(heading,LinearLayout.LayoutParams(0,-2,1f));bar.addView(text("v1",12,true));root.addView(bar);val sc=ScrollView(this);sc.addView(root);setContentView(sc)}
    private fun showHome(){base("PhoenixTunnel");root.addView(text("CONFIG v1.0  •  LOCAL",12,true));root.addView(card("${if(connected)"CONNECTED" else "DISCONNECTED"}\n↓ 0 KB/s      ↑ 0 KB/s\nSession  ${if(connected)"active" else "--:--"}"));root.addView(button(if(connected)"DISCONNECT" else "CONNECT",true){toggle()});root.addView(text("HOME     •     LOGS",14,true));root.addView(button("Home"){showHome()});root.addView(button("Logs"){showLogs()});root.addView(button("Servers"){showServers()});root.addView(button("Networks / tweak profiles"){showNetworks()});root.addView(button("Create Config"){showCreate()});root.addView(button("Import Config"){importDoc.launch(arrayOf("text/*","application/octet-stream"))});root.addView(button("Paste config"){showImport("")});root.addView(button("V2Ray URI Converter"){showConverter()});root.addView(button("Settings"){base("Settings");root.addView(text("PhoenixTunnel preferences",16,false))});root.addView(button("About"){base("About");root.addView(text("PhoenixTunnel personal VPN client",16,false))})}
    private fun drawer(){val choices=arrayOf("Home","Servers","Networks","Create Config","Import Config","V2Ray URI Converter","Tweak Lab","Logs","Settings","About");AlertDialog.Builder(this).setTitle("PhoenixTunnel").setItems(choices){_,i->when(i){0->showHome();1->showServers();2->showNetworks();3->showCreate();4->importDoc.launch(arrayOf("*/*"));5->showConverter();6->showLab();7->showLogs();else->{base(choices[i]);root.addView(text(choices[i],18,true))}}}.show()}
    private fun showServers(){base("Servers");root.addView(button("＋ Add server profile"){showCreate()});repo.listProfiles().forEach{p->val row=LinearLayout(this);row.addView(text("${p.name}  •  WireGuard",16,true),LinearLayout.LayoutParams(0,-2,1f));row.addView(button("Delete"){repo.deleteProfile(p.name);repo.addLog("Deleted profile ${p.name}");showServers()});root.addView(row);root.addView(button("Edit / view"){showImport(p.content,p.name)})};if(repo.listProfiles().isEmpty())root.addView(text("No profiles yet",16,false))}
    private fun showNetworks(){base("Networks");repo.listTweaks().forEach{p->root.addView(button("${if(p.active)"✓ " else ""}${p.name}  ·  ${p.protocol}"){repo.saveTweak(p.copy(active=true));repo.addLog("Activated tweak ${p.name}");showNetworks()})};root.addView(button("Add tweak profile"){tweakEditor()})}
    private fun tweakEditor(){val name=EditText(this).apply{hint="Profile name"};val protocol=EditText(this).apply{hint="Protocol"};val payload=EditText(this).apply{hint="Payload with [host], [crlf], [ua]"};val box=LinearLayout(this).apply{orientation=1;addView(name);addView(protocol);addView(payload)};AlertDialog.Builder(this).setTitle("Tweak profile").setView(box).setPositiveButton("Save"){_,_->try{val p=TweakProfile(name.text.toString(),protocol.text.toString(),payload.text.toString());TweakProfileJsonParser.parse(JSONObject().put("name",p.name).put("protocol",p.protocol).put("payload",p.payload).toString());repo.saveTweak(p);showNetworks()}catch(e:Exception){toast(e.message?:"Invalid tweak")}}.setNegativeButton("Cancel",null).show()}
    private fun showCreate(){base("Create Config");val protocol=Spinner(this).apply{adapter=ArrayAdapter(this@MainActivity,android.R.layout.simple_spinner_dropdown_item,TunnelProtocol.entries.map{it.label})};val name=EditText(this).apply{hint="Profile name"};val config=EditText(this).apply{hint="[Interface]\nPrivateKey = ...\nAddress = ...\n[Peer]\nPublicKey = ...\nEndpoint = host:port\nAllowedIPs = 0.0.0.0/0";minLines=8;gravity=Gravity.TOP};root.addView(protocol);root.addView(name);root.addView(config);root.addView(text("Payload placeholders: [host]  [crlf]  [ua]",13,false));root.addView(button("Test then save",true){try{val selected=TunnelProtocol.fromLabel(protocol.selectedItem.toString());val engine=TunnelEngines.forProtocol(selected);val result=engine.validate(config.text.toString());if(selected==TunnelProtocol.WIREGUARD)reachability(config.text.toString());repo.saveProfile(name.text.toString(),config.text.toString());repo.addLog("Saved ${name.text} after validation: $result");toast("Validated and saved");showServers()}catch(e:Exception){repo.addLog("Config rejected: ${e.message}");toast("Rejected: ${e.message}")}})}
    private fun reachability(s:String){val endpoint=WireGuardConfigParser.parse(s).endpoint;val host=endpoint.substringBeforeLast(':').removePrefix("[").removeSuffix("]");val port=endpoint.substringAfterLast(':').toIntOrNull()?:throw IllegalArgumentException("Endpoint port invalid");val ok=java.net.Socket().use{it.connect(java.net.InetSocketAddress(host,port),2500);true};if(!ok)throw IllegalArgumentException("Reachability check failed")}
    private fun showImport(content:String,name:String="Imported"){base("Import Config");val input=EditText(this).apply{setText(content);minLines=10;gravity=Gravity.TOP};val n=EditText(this).apply{hint="Profile name";setText(name)};root.addView(text("Paste a WireGuard .conf profile",14,false));root.addView(n);root.addView(input);root.addView(button("Validate and import",true){try{repo.importProfile(n.text.toString(),input.text.toString());repo.addLog("Imported profile ${n.text}");toast("Imported");showServers()}catch(e:Exception){toast("Import rejected: ${e.message}")}})}
    private fun showConverter(){base("V2Ray URI Converter");val input=EditText(this).apply{hint="vmess:// or vless://"};root.addView(input);root.addView(button("Convert / inspect",true){try{val c=V2RayUriParser.parse(input.text.toString());root.addView(card("${c.protocol.uppercase()}  ${c.server}:${c.port}\nID: ${c.id}\nNetwork: ${c.network}  TLS: ${c.tls}"))}catch(e:Exception){toast("Invalid URI: ${e.message}")}})}
    private fun showLogs(){base("Logs");root.addView(text("HOME     •     LOGS",14,true));root.addView(button("Home"){showHome()});root.addView(text(repo.logs(),14,false))}
    private fun toggle(){if(connected){stopService(Intent(this,TunnelService::class.java));connected=false;repo.addLog("Disconnected");showHome();return};val profile=repo.listProfiles().firstOrNull();if(profile==null){toast("Import or create a WireGuard profile first");return};val consent=VpnService.prepare(this);if(consent!=null)startActivityForResult(consent,9) else startTunnel(profile.content)}
    override fun onActivityResult(requestCode:Int,resultCode:Int,data:Intent?){super.onActivityResult(requestCode,resultCode,data);if(requestCode==9&&resultCode==Activity.RESULT_OK)repo.listProfiles().firstOrNull()?.let{startTunnel(it.content)}}
    private fun startTunnel(config:String){ContextCompat.startForegroundService(this,Intent(this,TunnelService::class.java).putExtra(TunnelService.EXTRA_CONFIG,config));connected=true;started=System.currentTimeMillis();repo.addLog("Connect requested");showHome()}

    private fun showLab(){base("Tweak Lab");root.addView(text("Connection diagnostics: one manual check per press. Single checks only, no automation.",13,false));val host=EditText(this).apply{hint="Host e.g. 1.1.1.1 or example.com"};val port=EditText(this).apply{hint="Port";inputType=android.text.InputType.TYPE_CLASS_NUMBER};val method=Spinner(this).apply{adapter=ArrayAdapter(this@MainActivity,android.R.layout.simple_spinner_dropdown_item,arrayOf("TCP","GET","POST","CONNECT"))};val template=EditText(this).apply{hint="Optional raw request template ([host] [ua] [crlf] [split])";minLines=4;gravity=Gravity.TOP};val out=TextView(this).apply{textSize=13f;setTextColor(0xffcbb9dd.toInt());setPadding(8,16,8,16)};root.addView(host);root.addView(port);root.addView(method);root.addView(template);root.addView(button("TEST",true){val h=host.text.toString().trim();val pt=port.text.toString().toIntOrNull();if(h.isEmpty()||pt==null||pt !in 1..65535){toast("Enter a valid host and port");return@button};out.text="testing $h:$pt ...";Thread{val t0=System.currentTimeMillis();try{java.net.Socket().use{sock->sock.connect(java.net.InetSocketAddress(h,pt),4000);val ms=System.currentTimeMillis()-t0;var resp="";val tmpl=template.text.toString();if(tmpl.isNotBlank()&&method.selectedItem.toString()!="TCP"){val req=tmpl.replace("[host]",h).replace("[ua]","Mozilla/5.0 (Linux; Android 16) PhoenixTunnel/1.0").replace("[crlf]","\r\n").replace("[split]","\r\n\r\n");sock.getOutputStream().write(req.toByteArray());sock.soTimeout=4000;resp=sock.getInputStream().bufferedReader().readLine()?:""};runOnUiThread{out.text="PASS  connect ${ms}ms\n$resp\n\nsaved? use SAVE AS PROFILE below"}}}catch(e:Exception){val ms=System.currentTimeMillis()-t0;runOnUiThread{out.text="FAIL after ${ms}ms: ${e.message}"}}}.start()});root.addView(button("SAVE AS PROFILE"){val h=host.text.toString().trim();val pt=port.text.toString();if(h.isEmpty()||pt.toIntOrNull()==null){toast("Fill host and port first");return@button};val name="lab-$h-$pt";repo.saveProfile(name,"[Interface]\nAddress = 10.13.13.2/32\nDNS = 1.1.1.1\n[Peer]\nEndpoint = $h:$pt\nAllowedIPs = 0.0.0.0/0\n# lab combo: ${method.selectedItem} ${template.text.toString().take(120)}");repo.addLog("Tweak Lab saved $name");toast("Saved $name");showServers()});root.addView(out)}
    private fun text(s:String,size:Float,bold:Boolean)=TextView(this).apply{text=s;textSize=size;setTextColor(if(bold)0xfff3e8ff.toInt() else 0xffcbb9dd.toInt());if(bold)setTypeface(null,1);setPadding(8,12,8,12)}
    private fun button(s:String,large:Boolean=false,action:()->Unit)=Button(this).apply{text=s;textSize=if(large)20f else 14f;setTextColor(-1);backgroundTintList=android.content.res.ColorStateList.valueOf(if(large)0xff8a2be2.toInt() else 0xff382553.toInt());setOnClickListener{action()};minimumHeight=if(large)150 else 48}
    private fun card(s:String)=TextView(this).apply{text=s;textSize=18f;setTextColor(-1);setPadding(22,24,22,24);background=android.graphics.drawable.GradientDrawable().apply{setColor(0xff26183b.toInt());cornerRadius=28f};layoutParams=LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,18,0,18)}}
    private fun toast(s:String)=Toast.makeText(this,s,Toast.LENGTH_LONG).show()
}
